def choose_move(observation):
    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def clamp1(v):
        return -1 if v < -1 else (1 if v > 1 else v)

    def pos(key, default=(0, 0)):
        p = observation.get(key, default)
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            return p[0], p[1]
        return default

    def dims():
        w = observation.get("grid_width", 0)
        h = observation.get("grid_height", 0)
        return (w if isinstance(w, int) else 0), (h if isinstance(h, int) else 0)

    def step_toward(a, b):
        return [clamp1(sign(b[0] - a[0])), clamp1(sign(b[1] - a[1]))]

    def step_away(a, b):
        return [clamp1(sign(a[0] - b[0])), clamp1(sign(a[1] - b[1]))]

    def best_by_distance(points, origin, fn=min):
        best = None
        best_score = None
        for p in points or []:
            if not isinstance(p, (list, tuple)) or len(p) < 2:
                continue
            score = abs(p[0] - origin[0]) + abs(p[1] - origin[1])
            if best is None or (fn is min and score < best_score) or (fn is max and score > best_score):
                best = p
                best_score = score
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos("self_position")
    ox, oy = pos("opponent_position", (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    w, h = dims()

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        corners = []
        if w > 0 and h > 0:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = best_by_distance(corners, opp_pos, fn=max)
        if target is None:
            return step_away(self_pos, opp_pos)
        return step_toward(self_pos, target)

    if env == "territory_control":
        candidates = []
        for k in ("unclaimed_cells", "opponent_territory", "border_cells", "targets"):
            v = observation.get(k)
            if v:
                candidates = v
                break
        if not candidates:
            return [0, 0]
        target = best_by_distance(candidates, self_pos, fn=min)
        if target is None:
            return [0, 0]
        move = step_toward(self_pos, target)
        if move == [0, 0]:
            return step_away(self_pos, opp_pos)
        return move

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        target = best_by_distance(resources, self_pos, fn=min)
        if target is not None:
            return step_toward(self_pos, target)

    # Generic fallback: move away from opponent if threatened, else drift toward center.
    if w > 0 and h > 0:
        center = (w // 2, h // 2)
        dist_opp = abs(sx - ox) + abs(sy - oy)
        if dist_opp <= 2:
            move = step_away(self_pos, opp_pos)
            if move != [0, 0]:
                return move
        return step_toward(self_pos, center)

    return step_away(self_pos, opp_pos)

